from collections import defaultdict, deque
import heapq


def shortest_path(edges, start, end):
    """
    Find the shortest path between start and end nodes in a directed graph with weighted edges.

    Args:
        edges: List of (from_node, to_node, weight) tuples representing one-way roads
        start: Starting node (str or hashable)
        end: Destination node (str or hashable)

    Returns:
        (distance, path): A tuple where distance is the total weight and path is an ordered list of nodes.

    Raises:
        ValueError: If any edge has a negative weight.
        Returns None values: If no path exists between start and end.
    """
    # Case when start == end
    if start == end:
        return (0, [start])

    # Build adjacency list
    graph = defaultdict(list)
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight not allowed")
        graph[from_node].append((to_node, weight))

    # Initialize Dijkstra's algorithm
    distances = {start: 0}
    predecessors = {}
    pq = [(0, start)]

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_dist > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph[current_node]:
            new_dist = current_dist + weight
            if neighbor not in distances or new_dist < distances[neighbor]:
                distances[neighbor] = new_dist
                predecessors[neighbor] = current_node
                heapq.heappush(pq, (new_dist, neighbor))

    # Check if end node is reachable
    if end not in distances:
        return (None, None)

    # Reconstruct path from end to start using predecessors
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessors.get(current)

    path.reverse()
    return (distances[end], path)
